export function slugify(input, options = {}) {
  const separator = options.separator === undefined ? "-" : options.separator;
  if (typeof separator !== "string" || separator.length === 0) {
    throw new TypeError("separator must be a non-empty string");
  }

  const maxLength = options.maxLength;
  if (
    maxLength !== undefined &&
    (!Number.isInteger(maxLength) || maxLength <= 0)
  ) {
    throw new TypeError("maxLength must be a positive integer");
  }

  let slug = String(input)
    .normalize("NFKD")
    .replace(/\p{M}+/gu, "")
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, separator);

  slug = slug.split(separator).filter(Boolean).join(separator);

  if (maxLength !== undefined) {
    const chars = Array.from(slug);
    if (chars.length > maxLength) {
      let cut = chars.slice(0, maxLength).join("");
      const lastSeparator = cut.lastIndexOf(separator);
      if (lastSeparator > 0) {
        cut = cut.slice(0, lastSeparator);
      }
      while (cut.endsWith(separator)) {
        cut = cut.slice(0, -separator.length);
      }
      slug = cut;
    }
  }

  return slug;
}
